    private static readonly Lazy<(string[] Names, Dictionary<string, string> Glyphs)> Parsed = new(() =>
    {
        var glyphs = new Dictionary<string, string>(StringComparer.Ordinal);
        foreach (var entry in Data.Split(';', StringSplitOptions.RemoveEmptyEntries))
        {
            var colon = entry.IndexOf(':');
            glyphs[entry[..colon]] = char.ConvertFromUtf32(int.Parse(entry[(colon + 1)..], System.Globalization.NumberStyles.HexNumber));
        }
        return ([.. glyphs.Keys.Order(StringComparer.Ordinal)], glyphs);
    });

    /// <summary>Names of every icon, sorted.</summary>
    public static IReadOnlyList<string> Names => Parsed.Value.Names;

    /// <summary>Glyph of the icon <paramref name="name"/>; null when the font has none of that name.</summary>
    public static string? GlyphOf(string? name) => name is not null && Parsed.Value.Glyphs.TryGetValue(name, out var glyph) ? glyph : null;
